export function phonopySourceHTML(r){
 const identity=r.sourceIdentity,reference=identity?.reference;if(!reference)return '';
 return `<aside class="obs-model-note"><h3>Official Al calculation example</h3><p>This Al / ABACUS plane-wave example comes from Phonopy. It contains published calculation data, not experimental data or a new calculation by this site. The primitive cell has one Al atom and three branches at each q point. Some input eigenvectors have relative phases between Cartesian components that cannot be removed by one overall phase. The example tests complex phase rendering for single-atom modes; it does not cover multi-atom optical branches or relative motion of atoms with unequal masses.</p><p>The band.yaml file does not declare a frequency unit. The example entry explicitly selects THz, consistent with the companion calculation settings and Phonopy's ABACUS conversion convention. This choice is retained as user confirmation.</p><div class="obs-links"><a href="${esc(reference.url)}" target="_blank" rel="noreferrer">Original file at pinned revision ↗</a><a href="data/examples/phonopy-al-abacus-LICENSE.txt" target="_blank">BSD three-clause license ↗</a><a href="docs/phonopy-import.md#official-al-example" target="_blank">Sources and activity ↗</a></div><details><summary>File identity and pinned revision</summary><p>Revision: ${esc(reference.commit)}; path: ${esc(reference.path)}。</p><pre>SHA-256: ${esc(identity.sha256)}\nUTF-8 bytes: ${identity.byteCount}</pre></details></aside>`;
}
const sources=(rows=[])=>`<div class="obs-sources">${rows.map(s=>typeof s==='string'?{url:s,title:s}:s).filter(s=>/^https:\/\//.test(s.url||'')).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.title||s.url)} ↗</a>`).join('')}</div>`;
export function phononBandSVG(r){
 const qs=r.qpoints||[];if(!qs.length)return '';
 const values=qs.flatMap(q=>q.frequencies).filter(Number.isFinite),ymin=Math.min(0,...values),ymax=Math.max(0,...values),dy=ymax-ymin||1;
 const haveDistance=qs.every(q=>Number.isFinite(q.distance)),xs=qs.map((q,i)=>haveDistance?q.distance:i),lo=Math.min(...xs),dx=Math.max(...xs)-lo||1;
 const p=(i,b)=>[65+590*(xs[i]-lo)/dx,260-220*(qs[i].frequencies[b]-ymin)/dy],palette=['#287c66','#ba7f37','#537eb0','#865a9c'];let lines='';
 for(const segment of r.segments||[])for(let b=0;b<(qs[0]?.frequencies.length||0);b++){const ids=segment.indices||Array.from({length:segment.end-segment.start+1},(_,j)=>j+segment.start);const pts=ids.filter(i=>qs[i]&&Number.isFinite(qs[i].frequencies[b])).map(i=>p(i,b));if(pts.length>1)lines+=`<polyline points="${pts.map(v=>v.join(',')).join(' ')}" fill="none" stroke="${palette[b%4]}" stroke-width="2"/>`;else if(pts.length)lines+=`<circle cx="${pts[0][0]}" cy="${pts[0][1]}" r="3" fill="${palette[b%4]}"/>`;}
 const boundaries=new Map();for(const segment of (r.segments||[]).slice(0,30)){for(const i of [segment.start,segment.end]){if(!qs[i]?.label)continue;const x=65+590*(xs[i]-lo)/dx,key=x.toFixed(2),entry=boundaries.get(key)||{x,labels:[]};if(!entry.labels.includes(qs[i].label))entry.labels.push(qs[i].label);boundaries.set(key,entry);}}
 const ticks=[...boundaries.values()].map(b=>`<path d="M${b.x} 35V260" stroke="#c8d4cc" stroke-dasharray="3 5"/><text x="${b.x}" y="290" text-anchor="middle">${esc(b.labels.join(' | '))}</text>`).join('');
 const si=r.selection?.qIndex??0,sb=r.selection?.bandIndex??0,selected=qs[si]&&p(si,sb);
 return `<svg class="obs-curve dyn-band" viewBox="0 0 720 325" role="img" aria-label="Segmented phonon dispersion;${esc(r.frequencyUnit)}"><title>is segmented by file path, and negative values represent the signed encoding of the imaginary frequency.</title><path d="M65 30V260H670" fill="none" stroke="#9daea8"/><path d="M65 ${260+220*ymin/dy}H670" stroke="#b6c7be" stroke-dasharray="5 4"/>${ticks}${lines}${selected?`<circle cx="${selected[0]}" cy="${selected[1]}" r="7" fill="#c65344" stroke="white" stroke-width="2"/>`:''}<text x="68" y="22">frequency / ${esc(r.frequencyUnit)} · ${num(ymin)} to ${num(ymax)}</text>${ticks?'':`<text x="65" y="288">${num(lo)}</text><text x="610" y="288">${num(Math.max(...xs))}</text>`}<text x="215" y="315">${haveDistance?"Cumulative path distance in the file / "+(r.structure?.reciprocalLengthUnit||"Input reciprocal-length unit"):"Independent q-point index (starting from 0)"}</text></svg>`;
}
export function phasorSVG(components){
 let x=0,y=0;const points=[[x,y]];for(const c of components||[]){x+=c.real;y+=c.imag;points.push([x,y]);}const max=Math.max(1,...points.flatMap(p=>p.map(Math.abs))),project=p=>[320+130*p[0]/max,175-130*p[1]/max];
 return `<svg class="obs-curve" viewBox="0 0 640 370" role="img" aria-label="Complex plane end-to-end addition of atomic scattering amplitudes"><title>Scattering amplitude phase addition</title><defs><marker id="dyn-phasor-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#b7833f"/></marker></defs><path d="M40 175H600M320 25V320" stroke="#c3cec7"/>${points.slice(1).map((p,i)=>{const a=project(points[i]),b=project(p);return `<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="#b7833f" stroke-width="2" marker-end="url(#dyn-phasor-arrow)"/><circle cx="${b[0]}" cy="${b[1]}" r="3" fill="#b7833f"/>`;}).join('')}<line x1="320" y1="175" x2="${project([x,y])[0]}" y2="${project([x,y])[1]}" stroke="#287c66" stroke-width="4"/><text x="30" y="350">Gold: add the atomic contributions; green: total amplitude F (same axis scale)</text><text x="560" y="160">Re F</text><text x="335" y="30">Im F</text></svg>`;
}
